import sys; from pathlib import Path
sys.path.insert(0, str(Path.cwd()))
try:
    from app import clamp
    for value, low, high, expected in [(-1, 0, 10, 0), (0, 0, 10, 0), (5, 0, 10, 5), (10, 0, 10, 10), (11, 0, 10, 10), (0, 0, 0, 0), (-2.5, -2, -1, -2), (-1.5, -2, -1, -1.5)]:
        assert clamp(value, low, high) == expected
    try:
        clamp(5, 10, 0)
    except ValueError:
        pass
    else:
        raise AssertionError('inverted bounds were accepted')
except BaseException as error:
    raise SystemExit('clamp verification did not complete: ' + type(error).__name__ + ': ' + str(error))
